import{_ as i,o as t,c as a,ag as s}from"./chunks/framework.BSwSpTvy.js";const r="/zed-custom/skill-invocation.gif",o="/zed-custom/skill-creation.gif",m=JSON.parse(`{"title":"🧠 Skill Library: The AI's Expertise Engine","description":"","frontmatter":{},"headers":[],"relativePath":"features/skill-library.md","filePath":"features/skill-library.md"}`),l={name:"features/skill-library.md"};function n(c,e,d,h,p,u){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="🧠-skill-library-the-ai-s-expertise-engine" tabindex="-1">🧠 Skill Library: The AI&#39;s Expertise Engine <a class="header-anchor" href="#🧠-skill-library-the-ai-s-expertise-engine" aria-label="Permalink to &quot;🧠 Skill Library: The AI&#39;s Expertise Engine&quot;">​</a></h1><p>The <strong>Skill Library</strong> is the foundational system that transforms a generic Large Language Model into a <strong>specialized software engineer</strong> tailored to your specific stack, architecture, and team conventions.</p><hr><h2 id="🚀-instant-discovery" tabindex="-1">🚀 Instant Discovery <a class="header-anchor" href="#🚀-instant-discovery" aria-label="Permalink to &quot;🚀 Instant Discovery&quot;">​</a></h2><p>Zed Custom makes your expertise discoverable and reachable in seconds.</p><h3 id="_1-instant-invocation-slash-commands" tabindex="-1">1. Instant Invocation (Slash Commands) <a class="header-anchor" href="#_1-instant-invocation-slash-commands" aria-label="Permalink to &quot;1. Instant Invocation (Slash Commands)&quot;">​</a></h3><p><img src="'+r+`" alt="Skill Invocation"></p><p>Every skill in your library is automatically registered as a <strong>Slash Command</strong>. Type <code>/rust</code> or <code>/tailwind</code> directly in the chat.</p><ul><li><strong>Command Palette</strong>: Search for &quot;Skill Library&quot; or hit <code>cmd-shift-s</code>.</li><li><strong>Contextual UI</strong>: Manage your skills in a dedicated tab with a full IDE-grade editor.</li></ul><hr><h2 id="📂-hybrid-expertise-system" tabindex="-1">📂 Hybrid Expertise System <a class="header-anchor" href="#📂-hybrid-expertise-system" aria-label="Permalink to &quot;📂 Hybrid Expertise System&quot;">​</a></h2><p>Skills are managed through two parallel systems, giving you the best of both world: <strong>Shared Team Standards</strong> and <strong>Personal Library expertise</strong>.</p><h3 id="_1-global-skill-library-personal" tabindex="-1">1. Global Skill Library (Personal) <a class="header-anchor" href="#_1-global-skill-library-personal" aria-label="Permalink to &quot;1. Global Skill Library (Personal)&quot;">​</a></h3><p>Stored in a local high-performance database, these skills follow you across all your projects.</p><ul><li><strong>Pinned Skills</strong>: Toggle the <strong>Paperclip icon</strong> to include a skill in the permanent system prompt of every conversation.</li><li><strong>Expert Templates</strong>: Comes pre-loaded with experts for Rust Security, Tailwind CSS, and Commit Message generation.</li></ul><h3 id="_2-project-specific-skills-team" tabindex="-1">2. Project-Specific Skills (Team) <a class="header-anchor" href="#_2-project-specific-skills-team" aria-label="Permalink to &quot;2. Project-Specific Skills (Team)&quot;">​</a></h3><p>Zed Custom natively supports &quot;File-based&quot; skills that you can check into Git. These files are automatically detected by <strong>Zed&#39;s Assistant Panel</strong> and prioritized whenever you are working within that specific project folder.</p><p>This is incredibly useful for enforcing team-wide coding standards, architectural patterns, or API keys directly within your repository.</p><p><strong>Supported File Names:</strong></p><ul><li><strong><code>.rules</code> / <code>.cursorrules</code></strong>: Read globally for the entire project.</li><li><strong><code>AGENT.md</code></strong>: Best for high-level architectural constraints or documenting complex state.</li><li><strong><code>.python_rules</code> / <code>.cpp_rules</code></strong>: Language-specific expertise injected only when relevant.</li></ul><h4 id="🍼-step-by-step-creating-a-team-rule-file" tabindex="-1">🍼 Step-by-Step: Creating a Team Rule File <a class="header-anchor" href="#🍼-step-by-step-creating-a-team-rule-file" aria-label="Permalink to &quot;🍼 Step-by-Step: Creating a Team Rule File&quot;">​</a></h4><p>These are just plain text files that the Zed Assistant reads automatically. Here is how to create one:</p><ol><li><strong>Open your project</strong> in Zed Custom.</li><li><strong>Create a new file</strong> in the root folder of your project.</li><li><strong>Name the file</strong> <code>.cursorrules</code> (make sure it starts with a dot!).</li><li><strong>Paste instructions</strong> into the file. For example:<div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># My Coding Rules</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Always use explicit error handling.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Never use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`unwrap()\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> or similar panicking functions.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Document every public function.</span></span></code></pre></div></li><li><strong>Save the file.</strong></li></ol><p>That&#39;s it! Zed&#39;s Assistant will immediately detect this file and automatically include those specific instructions in the system prompt for every new chat you start in this project. You can even check this file into Git so your entire team&#39;s Assistant acts the exact same way.</p><hr><h2 id="🛠️-managing-your-skills" tabindex="-1">🛠️ Managing Your Skills <a class="header-anchor" href="#🛠️-managing-your-skills" aria-label="Permalink to &quot;🛠️ Managing Your Skills&quot;">​</a></h2><p><img src="`+o+'" alt="Skill Creation"></p><div class="features-grid"><div class="feature-card"><h3>📝 Rich Editor</h3><p>Edit your prompts with full syntax highlighting, auto-indentation, and Markdown support.</p></div><div class="feature-card"><h3>🪄 Inline Refinement</h3><p>Highlight any part of your skill and use <code>cmd-i</code> to have the AI help you rewrite or clear up your instructions.</p></div><div class="feature-card"><h3>🔗 Pinned Persistence</h3><p>Pinned skills benefit from &quot;Recency Bias&quot; injection, ensuring your most important constraints are never forgotten by the model.</p></div></div><hr><h2 id="⚡-real-world-example" tabindex="-1">⚡ Real-World Example <a class="header-anchor" href="#⚡-real-world-example" aria-label="Permalink to &quot;⚡ Real-World Example&quot;">​</a></h2><p>If you have a <strong>&quot;Performance Expert&quot;</strong> skill pinned with these instructions:</p><blockquote><p>&quot;Always optimize for zero-allocation paths. Prefer <code>SmallVec</code> over <code>Vec</code> for small lists.&quot;</p></blockquote><p>The agent will automatically align its code suggestions without you ever mentioning performance in the chat:</p><div class="zed-chat-mockup"><div class="user-msg">&quot;Write a function to collect 4 string IDs.&quot;</div><div class="assistant-msg"><small>Consulting <b>Performance Expert</b> skill...</small><br> &quot;Using <code>SmallVec&lt;[String; 4]&gt;</code> to ensure zero heap allocations for this fixed-size list.&quot; </div></div><hr><h2 id="💎-pro-tips-for-high-quality-docs" tabindex="-1">💎 Pro-Tips for High-Quality Docs <a class="header-anchor" href="#💎-pro-tips-for-high-quality-docs" aria-label="Permalink to &quot;💎 Pro-Tips for High-Quality Docs&quot;">​</a></h2><ul><li><strong>Precedence</strong>: Project files always overwrite Library skills of the same name.</li><li><strong>Scoping</strong>: Use directory-level <code>.rules</code> files to give sub-modules their own specialized logic.</li><li><strong>Slugification</strong>: A skill named &quot;Rust Security Auditor&quot; will always be available as <code>/rust-security-auditor</code>.</li></ul><hr><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Getting Started</strong>: Create a new skill called &quot;My Preferences.&quot; Add instructions like &quot;I prefer explicit error handling over <code>.unwrap()</code>&quot; and pin it with the paperclip. Your AI will immediate feel like it has been working with you for years.</p></div>',39)])])}const y=i(l,[["render",n]]);export{m as __pageData,y as default};
